exercise.solution:
fn add_four_and_five(numbers: &mut Vec<i32>) {
    numbers.push(4);
    numbers.push(5);
}

fn main() {
    let mut numbers = vec![1, 2, 3];
    add_four_and_five(&mut numbers);
    println!("{:?}", numbers);
}
